	@Test
	void leavesNestedGraphAndServiceBodiesOutsideSelectedGraphScope() {
		IRI selectedGraph = SimpleValueFactory.getInstance().createIRI("urn:selectedGraph");
		StatementPattern selectedBody = new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o"));
		StatementPattern nestedGraphBody = new StatementPattern(Var.of("gs"), Var.of("gp"), Var.of("go"));
		Graph nestedGraph = new Graph(Var.of("nestedGraph"), nestedGraphBody);
		StatementPattern serviceBody = new StatementPattern(Var.of("ss"), Var.of("sp"), Var.of("so"));
		Service service = new Service(Var.of("service", SimpleValueFactory.getInstance().createIRI("urn:service")),
				serviceBody, "?ss ?sp ?so", null, null, false);
		Join plan = new Join(selectedBody, new Join(nestedGraph, service));

		plan.visit(new GraphScopeSpecializer(selectedGraph));

		assertThat(((StatementPattern) plan.getLeftArg()).getScope())
				.isEqualTo(StatementPattern.Scope.NAMED_CONTEXTS);
		assertThat(nestedGraphBody.getScope()).isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
		assertThat(serviceBody.getScope()).isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
	}

	@Test
	void specializingTripleRefJoinGroupDoesNotMutateReusablePlan() {
		QueryInfo queryInfo = mock(QueryInfo.class);
		TripleRefStatementPattern tripleRef = new TripleRefStatementPattern(
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("triple")),
				new TripleRef(Var.of("tripleSubject"), Var.of("triplePredicate"), Var.of("tripleObject"),
						Var.of("triple")),
				queryInfo);
		StatementPattern groupedStatement = new StatementPattern(Var.of("s"), Var.of("p2"), Var.of("o"));
		TripleRefJoinGroup group = new TripleRefJoinGroup(tripleRef, List.of(groupedStatement), List.of(), queryInfo);
		QueryRoot originalPlan = new QueryRoot(group);
		QueryRoot selectedPlan = originalPlan.clone();
		SimpleDataset inputDataset = new SimpleDataset();
		inputDataset.addNamedGraph(RDF4J.NIL);
		Dataset executionDataset = new GraphExecutionDataset(inputDataset);

		selectedPlan.getArg().visit(new GraphScopeSpecializer(new ActiveGraph(RDF4J.NIL, null), executionDataset));

		TripleRefJoinGroup selectedGroup = (TripleRefJoinGroup) selectedPlan.getArg();
		assertThat(selectedGroup.getTripleRefStatementPattern()).isNotSameAs(tripleRef);
		assertThat(selectedGroup.getTripleRefStatementPattern().getExecutionDataset()).isSameAs(executionDataset);
		assertThat(selectedGroup.getTripleRefStatementPattern().getParentNode()).isSameAs(selectedGroup);
		assertThat(selectedGroup.getStatementPatterns()).isNotSameAs(group.getStatementPatterns());
		assertThat(selectedGroup.getStatementPatterns().getFirst()).isNotSameAs(groupedStatement);
		assertThat(selectedGroup.getStatementPatterns().getFirst().getParentNode()).isSameAs(selectedGroup);
		assertThat(group.getTripleRefStatementPattern()).isSameAs(tripleRef);
		assertThat(group.getExecutionDataset()).isNull();
		assertThat(tripleRef.getParentNode()).isSameAs(group);
		assertThat(groupedStatement.getParentNode()).isSameAs(group);
		assertThat(tripleRef.getScope()).isEqualTo(StatementPattern.Scope.DEFAULT_CONTEXTS);
	}
